    double E[16][18];
    double A[16][20];
    double B[20][18];
    double F[18][22];
    double C[18][24];
    double D[24][22];
    double G[16][22];

    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    kernel_3mm(E, A, B, F, C, D, G);

    print_array(ni, nl, G);

    return 0;
}
